Method.Source:
    protected void setValues()
    {
        InventSum       inventSum = common;
        InventTable     inventTable = InventTable::find(inventSum.ItemId);
        Qty             physicalAvail = inventSum.AvailPhysical;
        Qty             physicalInvent = inventSum.PhysicalInvent;
        str             unit = inventTable.inventUnitId();
        str             quantityStr = MobHelper::formatItemQty(physicalAvail, unit);
        str             physicalInventStr = MobHelper::formatItemQty(physicalInvent,unit);
        str             itemName;
        MobCarts		carts;

        super();
        inventDim = inventSum.inventDim();
        imageId = MobHelper::imageIDFromDocuref(MobHelper::FindItemDocuref(inventSum.itemId,inventSum.InventDimId));
        itemName = inventTable.productName(new xInfo().language());
        displayLine2 = itemName;
        displayLine3 = '';

        select firstonly carts where carts.InventSiteId == inventDim.InventSiteId && carts.InventLocationId == inventDim.InventLocationId && carts.WMSLocationId == inventDim.wMSLocationId;

		if (carts)
        {
            displayLine1 = strFmt('%1: %2 (%3)',"@MobileWMS:Cart", carts.CartID, inventDim.wMSLocationId);
            displayLine5 = (carts.Note ? carts.Note + "@MobileWMS:lineBreak" : '' ) + MobReservedCarts::reserveInfo(carts.CartID);
        }
		else
		{
            displayLine1 = inventDim.wMSLocationId;
        }
        if (inventDim.LicensePlateId)
        {
            displayLine3 = strFmt("@MobileWMS:LPShort",inventDim.LicensePlateId);// + ' '+displayLine3;
        }
        #if.isAX6
        if (inventDim.wMSPalletId)
        {
            displayLine2 = strFmt("@MOB157",inventDim.wMSPalletId) + ' '+displayLine2;
        }
        #endif

        //quantityStr = (_InventLocationId == '' ? #SigmaCharacter + ' ' : '')+  MobHelper::formatItemQty(_physicalAvail, _unit)+ ' / '+MobHelper::formatItemQty(_physicalInvent,_unit);
        //quantityStr = MobHelper::formatItemQty(_physicalAvail, _unit);
        //physicalInventStr = MobHelper::formatItemQty(_physicalInvent,_unit);

        if (inventDim.inventBatchId)
        {
            displayLine3 += (displayLine3 ? ' / ' : '') + MobHelper::strFmt("@MobileWMS:MobileWMS155", [inventDim.inventBatchId]);
        }
        if (inventDim.inventSerialId)
        {
            displayLine3 += (displayLine3 ? ' / ' : '') + MobHelper::strFmt("@MobileWMS:MobileWMS156", [inventDim.inventSerialId]);
        }


        displayLine4 = '';
        if (inventDim.configId)
        {
            displayLine4 = SysLabel::labelId2String2("@SYS14011") + ': ' + inventDim.configId + '  ';
        }

        if (inventDim.InventSizeId)
        {
            displayLine4 += SysLabel::labelId2String2("@SYS28127") + ': ' + inventDim.InventSizeId + '  ';
        }

        if (inventDim.InventStyleId)
        {
            displayLine4 += SysLabel::labelId2String2("@SYS92859") + ': ' + inventDim.InventStyleId + '  ';
        }

        if (inventDim.InventColorId)
        {
            displayLine4 += SysLabel::labelId2String2("@SYS30436") + ': ' + inventDim.InventColorId;
        }

        fieldsToAdd.insert(MobConstants::UnitOfMeasure(), unit);
        fieldsToAdd.insert(MobConstants::Quantity(), quantityStr);
        fieldsToAdd.insert(extendedTypeStr(InventQtyTotal), physicalInventStr);
        fieldsToAdd.insert(MobConstants::ItemNumber(), InventSum.ItemId);

        //fieldsToAdd.insert('Warehouse', inventSum.RecId mod 2 ? '28' : '22');
    }
